const clamp=(n,a,b)=>Math.min(b,Math.max(a,n));
function fresh(sex,seed,origin="shop"){
 const s={version:6,sex,seed:seed>>>0,initialSeed:seed>>>0,origin,turn:1,role:"",team:"",stats:[44,45,44,67],fit:0,world:0,regional:0,titles:0,account:newAccount(),flags:{},history:[],pending:null,end:null};
 apply(s,ORIGINS[origin].delta);s.account.cash=ORIGINS[origin].cash;return s;
}
function draw(s){s.seed=(s.seed+0x6D2B79F5)>>>0;let b=Math.imul(s.seed^(s.seed>>>15),s.seed|1);b^=b+Math.imul(b^(b>>>7),b|61);return((b^(b>>>14))>>>0)/4294967296;}
function apply(s,delta){const old=s.stats.slice();s.stats=s.stats.map((v,i)=>clamp(v+(delta[i]||0),0,100));return s.stats.map((v,i)=>v-old[i]);}
const hand=[4,0,2,1],voices=[1,4,1,1],hours=[1,1,4,1],stamina=[1,1,1,4];
const outcome=(text,delta=[],marks={},ending="")=>({text,delta,marks,ending});
const scene=(title,body,art,options,extra={})=>({title,body,art,options,...extra});
const decision=(title,hint,icon,base,weights,success,failure,contest=false,target="完成这次配合")=>({title,hint,icon,base,weights,success,failure,contest,target});
const teamName=s=>CLUBS[s.team]?.name||"未签约";
function choose(title,hint,ok,no,marks={},delta=[0,2,1,0],base=62,ending="",icon="signal"){
 return decision(title,hint,icon,base,voices,outcome(ok,delta,marks,ending),outcome(no,delta.map(x=>x>0?Math.max(0,x-1):x),marks,ending),false,"后续进展");
}
function chance(s,c){
 const w=c.weights.reduce((n,v)=>n+v,0),score=s.stats.reduce((n,v,i)=>n+v*c.weights[i],0)/w;
 return clamp(Math.round(c.base+(score-60)*.45+(c.bonus||0)+(c.contest?s.fit:0)),8,93);
}
function chapter(s){return s.turn<=6?"青训营":s.turn<=13?"春季联赛":s.turn<=17?"夏季联赛":s.turn<=21?"首个世界赛季":s.turn<=25?"换队与重建":s.turn<=28?"第二个世界赛季":"职业去向";}
function ageAt(s){return Math.max(ages[s.turn-1],s.ageFloor||0);}
function stageName(s){return seasonTitles[s.turn-1];}
function sceneRecord(s,e){return {title:e.title,body:e.body,art:e.art,stage:e.stage||stageName(s),map:e.map,options:e.options.map(c=>({title:c.title,hint:c.hint,icon:c.icon,target:c.target}))};}
function move(s,i){
 if(s.pending||s.end)return false;
 const e=getScene(s),c=e.options[i];if(!c)return false;
 const odds=chance(s,c),roll=1+Math.floor(draw(s)*100),win=roll<=odds,result=win?c.success:c.failure;
 const snapshot=sceneRecord(s,e),delta=apply(s,result.delta),entries=[];
 const {newRole,newTeam,money,fit,trophy,...marks}=result.marks;
 if(newRole)s.role=newRole;if(newTeam)s.team=newTeam;if(fit!==undefined)s.fit=fit;Object.assign(s.flags,marks);
 if(result.marks.practice)recordPractice(s,result.marks.practice);
 if(money)for(const op of money)book(s,op,entries);
 if(trophy){s[trophy]++;s.titles++;book(s,["earn",trophy==="world"?10:3,trophy==="world"?"世界冠军个人奖金":"赛区冠军个人奖金"],entries);if(trophy==="world"&&s.flags.deal==="bonus")book(s,["earn",6,"成绩条款兑现"],entries);if(trophy==="world"&&s.flags.deal==="equity")book(s,["earn",4,"本期项目收益分配"],entries);}
 const h={turn:s.turn,index:i,age:ageAt(s),title:e.title,choice:c.title,text:result.text,delta,entries,odds,roll,win,role:s.role,team:s.team,snapshot,target:c.target,ending:result.ending,trophy:trophy||"",art:result.art||"",tactic:e.tactic||"",official:!!e.official};
 if(e.scoreline)h.text+=" "+e.scoreline[win?0:1];
 if(!h.ending&&e.quarter)series(s,h,e.quarter==="B");
 if(h.ending)h.ending=resolveEnding(s,h.ending);
 payStages(s,h);h.photos=frameBinding(s,h,e);
 s.history.push(h);s.pending=true;return true;
}
function series(s,h,second){
 const f=s.flags;const personal=h.win&&f.registration!=="reserve";
 const rate=clamp(Math.round((h.win?61:35)+s.fit+(f.registration==="reserve"?-14:0)+(s.stats[2]-55)*.18),12,90);
 const roll=1+Math.floor(draw(s)*100),won=roll<=rate;f[second?"qB":"qA"]=won;
 if(!won&&personal)f.selfRescue=true;
 const note=won?"整轮系列赛打完，你们拿到四强名额。":personal?"你替队伍扳回一局，对手还是赢下了系列赛。离场前你回头看了一眼，知道自己这次没有放过能出手的机会。":"系列赛止步八强。教练留下了这局的五份选手视角，等大家回基地复盘。";
 h.series={odds:rate,roll,win:won,note};h.text+=" "+note;
}
function advance(s){
 if(!s.pending||s.end)return false;const h=s.history.at(-1);if(h.ending){s.end=h.ending;s.pending=null;return true;}
 if(s.turn===30)throw Error("末轮缺少结局");
 h.daily=interlude(s,h);s.turn++;s.pending=null;return true;
}

const roundMoney=n=>Math.round((n+Number.EPSILON)*100)/100;
function newAccount(){return {income:0,debt:0,cash:0,due:0,held:0,stream:0};}
function book(s,[type,quote,note],log){
 if(!Number.isFinite(quote)||quote<0)throw Error("账目金额无效");
 const a=s.account;let value=roundMoney(quote);
 switch(type){
 case "earn":case "broadcast":a.income+=value;a.cash+=value;if(type==="broadcast")a.stream+=value;break;
 case "borrow":a.cash+=value;a.debt+=value;break;
 case "repay":value=Math.min(a.cash,a.debt,value);a.cash-=value;a.debt-=value;break;
 case "spend":case "hold":
  if(value>a.cash+0.001)throw Error("未说明资金来源："+note);
  a.cash-=value;if(type==="hold")a.held+=value;break;
 case "release":value=Math.min(a.held,value);a.held-=value;a.cash+=value;break;
 case "accrue":a.due+=value;break;
 case "collect":value=Math.min(a.due,value);a.due-=value;a.cash+=value;a.income+=value;break;
 default:throw Error("未知账目："+type);
 }
 for(const k in a)a[k]=roundMoney(a[k]);if(value)log.push({type,value,note});
}
const LINEUPS={
 red:[["阔石","擅长单线推进，边路愿意先行"],["远湾","擅长先行，等线上队友前移后再转线"],["折柳","擅长轮转，先把光标送过中路计分门"],["浅野","擅长连续送标，需要有人垫后"],["汀禾","擅长先行和换线，愿意替搭档打开接应空间"]],
 black:[["岑原","擅长接应和守门，愿意让出交接次数"],["乌檐","习惯先行，进入联络区前会查两侧队友位置"],["鸣沙","擅长先行与轮转，正在补接应课"],["灯渡","擅长连续送标，比赛后段节奏稳定"],["临舟","习惯跟打野轮转，搭档离开下路时，射手需要独立接棒"]],
 gold:[["鸣岭","单线推进很稳，转回中路要提前回位"],["循川","擅长守门和轮转，重视每轮充能"],["砚池","擅长接应，愿把中路的送标机会分给边线"],["连雨","擅长连续送标，与辅助磨合了两个赛季"],["停云","擅长陪跑与接应，通常与下路并行"]],
 white:[["石渐","擅长守门，独自接边线时善于节省充能"],["青渡","习惯替线上接应，抢时间窗口时偏保守"],["安桥","擅长轮转，能替边路接下一次传递"],["白枫","新人下路，连续送标很稳，比赛经验仍需积累"],["鹭生","擅长先行，刚进入赛区联赛"]]
};
function roster(s,team=s.team,transfer=s.flags.rosterChange){
 if(!LINEUPS[team])return [];
 return LINEUPS[team].map(([id,style],i)=>{
  const role=ROLES[i];
  if(role===s.role)return {role,name:"你",style:"当前首发位置"};
  if(transfer==="duo"&&role===duoRole(s)&&s.flags.carryMate)return {role,name:s.flags.carryMate,style:s.flags.carryStyle||"随你一同转入的搭档"};
  if(transfer==="rebuild"&&i===(ROLES.indexOf(s.role)+1)%5)return {role,name:"新秀·溪声",style:"新提拔的替补，尚未与主力打过完整赛段"};
  return {role,name:id,style};
 });
}
function duoRole(s){return ({上单:"打野",打野:"中单",中单:"打野",下路:"辅助",辅助:"下路"})[s.role]||"打野";}
function teammate(s,team){return roster(s,team,team===s.team?s.flags.rosterChange:null).find(x=>x.role===duoRole(s));}
function rosterLine(s,team,mode){return roster(s,team,mode).filter(x=>x.name!=="你").map(x=>x.role+" "+x.name).join(" · ");}
function offerBase(s){return 11+4*s.regional+9*s.world+(s.flags.fame?2:0)+(s.flags.finalA?2:0);}
function dealOptions(s){
 const base=offerBase(s),others=Object.keys(CLUBS).filter(k=>k!==s.team);
 const release=s.flags.exitFee||2,bridge=Math.max(0,roundMoney(release-s.account.cash));
 const plans=[
 {id:"stay",t:s.team,base:base,term:"续约留队",detail:"熟悉的训练组继续保留你的上场名额；一名主力转出，由青训补位。",fit:[4,-1],odds:72,change:"rebuild"},
 {id:"strong",t:others[0],base:base+2,term:"换队备战",detail:"新队保留核心，你需要承担 "+release+" 万买断分摊"+(bridge?"，其中借 "+bridge+" 万":"，使用存款")+"。首发仍需竞争。",fit:[6,-5],odds:52,change:"strong"},
 {id:"loan",t:others[1],base:base-1,term:"一季书面租借",detail:"原队承担退出费用，新队给固定上场机会；租期结束，续留须三方另签。",fit:[3,-3],odds:66,change:"loan"},
 {id:"equity",t:others[2],base:base-2,term:"保底加项目分成",detail:"取得 5% 项目收益份额，本合同期世界夺冠才出现可分配利润，届时另分 4 万。",fit:[4,-4],odds:60,change:"equity"},
 {id:"bonus",t:others[0],base:base-2,term:"保底加成绩奖",detail:"进世界赛再奖 2 万，世界夺冠另奖 6 万。奖金取决于赛果。",fit:[5,-5],odds:49,change:"target"}
 ];
 const pairCost=roundMoney(base*.85),pairGap=Math.max(0,roundMoney(pairCost-s.account.cash));
 plans.push({id:"duo",t:others[1],base,term:"带搭档冲首发",detail:"新队肯给两个席位，但预算只够买断一人。你愿意为搭档分摊 "+pairCost+" 万，现款支付 "+roundMoney(pairCost-pairGap)+" 万"+(pairGap?"，其余 "+pairGap+" 万签借据":"")+"。两人必须重新争首发。",fit:[7,-3],odds:57,change:"duo"});
 return plans.map((p,i)=>{
  const prior=teammate(s,s.team),next=teammate(s,p.t);const same=p.id==="stay",duo=p.id==="duo";
  const cast=same?(ROLES[(ROLES.indexOf(s.role)+1)%5]===duoRole(s)?"旧搭档 "+prior.name+" 的位置改由新人接替。":"旧搭档 "+prior.name+" 留队。"):duo?"将 "+(prior?.name||"")+" 一同带走。":"新搭档 "+next.name+"（"+next.style+"）。";
  const prospective=roster({...s,flags:{...s.flags,carryMate:prior?.name,carryStyle:prior?.style}},p.t,p.change);
  const hint=clubRead(s,p.t)+" "+p.detail+" "+cast+" 拟定阵容："+prospective.map(x=>x.role+" "+x.name).join("、")+"。";
  function done(win){
   const money=p.id==="strong"?[...(bridge?[["borrow",bridge,"买断分摊借款"]]:[]),["spend",release,"提前解约分摊"]]:duo?payGap(s,pairCost,"搭档转会买断分摊"):[];
   const marks={newTeam:p.t,deal:p.id,fit:p.fit[win?0:1],contract:same?"stay":"transfer",rosterChange:p.change,termPay:p.base,oldPrepaid:false,carryMate:duo?prior.name:"",carryStyle:duo?prior.style:"",money};
   const sceneText=win?"新阵容试打时，两条边线同时送标过门，中路因此可以先到联络区。":"新阵容合练时，边路还没完成接棒，中路已经动身。两次交接都慢了，教练把这段列为下周专项。";
   return outcome("你签了"+CLUBS[p.t].name+"的"+p.term+"合同。合同期保底 "+p.base+" 万，分四次实际发放。"+sceneText,win?[2,2,1,0]:[0,-1,2,-1],marks);
  }
  return decision(p.term+" · "+CLUBS[p.t].name+" "+p.base+" 万",hint,"contract",p.odds,voices,done(true),done(false),false,"新阵容配合");
 });
}
function windowScene(s){
 const r=teammate(s,s.team),options=dealOptions(s);
 if(s.world>0){
  const next=Object.keys(CLUBS).find(k=>k!==s.team),pay=offerBase(s)+1;
  options.push(decision("跨赛区签下首发 · "+CLUBS[next].name+" "+pay+" 万","刚拿到世界冠军，另一赛区才来谈。新的中路和打野搭档要重新分工，复盘还要适应另一种语言；保底分四期到账。","contract",46,voices,...[true,false].map(ok=>outcome(ok?"领队安排了双语复盘，初次合练就能接上打野的回传。":"入队后有两次支援慢了半拍。新合同生效，接下来要重练配合。",[1,ok?2:-1,2,-1],{newTeam:next,deal:"abroad",termPay:pay,oldPrepaid:false,contract:"transfer",rosterChange:"strong",fit:ok?4:-5}))));
 }
 return scene("转会窗还有三天",teamName(s)+"愿意续约。"+r.name+"说自己也在谈合同，留不留还没定。经纪人把报价列成同一个期限：四期保底总额；首发、买断、奖金和分红另算。\n\n你有 "+s.account.cash+" 万现金、"+s.account.debt+" 万债务。俱乐部根据你的出场经历、赛区冠军和世界赛成绩报价。","team",options);
}
function payStages(s,h){
 const f=s.flags,t=h.turn;
 const first=[7,10,13,17].includes(t),later=[23,25,28,30].includes(t);
 const paidKey=first?"paidFirst":"paidNew";
 if(!s.flags.stopReason&&(first||later)&&(f[paidKey]||0)<4&&!(later&&f.oldPrepaid)){
  f[paidKey]=(f[paidKey]||0)+1;
  const total=first?(f.youthPay||6):(f.termPay||offerBase(s));const part=roundMoney(total/4);
  if(t===10&&f.payTiming==="deferred")book(s,["accrue",part,"俱乐部延后发放的一期保底"],h.entries);
  else book(s,["earn",part,"合同保底分期"],h.entries);
 }
 if((t===13||t===23||h.ending)&&s.account.due)book(s,["collect",s.account.due,"补发到期薪酬"],h.entries);
 if(t===25&&f.seedB&&f.deal==="bonus")book(s,["earn",2,"世界赛入围奖金"],h.entries);
 if((t===21||t===28||h.ending)&&s.account.held)book(s,["release",s.account.held,"手续完成，保证金返还"],h.entries);
 if([11,18,26].includes(t)&&h.choice.includes("录一期公开复盘")&&f.social==="fans"&&h.win)book(s,["broadcast",1.2,"公开复盘节目酬劳"],h.entries);
 if(t===29&&f.intent==="stream")book(s,["broadcast",h.win?4.2:1.6,"三期节目分成"],h.entries);
 if(h.ending==="wealthStream"){
  const earnings=24+4*(f.audience||0)+3*s.titles;
  book(s,["broadcast",earnings,"转型后首年已兑现的平台保底与订阅分成"],h.entries);
  h.text+=" 转型后的首个年度，你的栏目合计到账 "+earnings+" 万。"+(s.account.debt?"你拿出其中一部分归还借款。":"对完结算单，你和编辑排起了下一季的节目。");
  if(s.account.debt)book(s,["repay",s.account.debt,"直播收入偿还旧债"],h.entries);
 }
}
function payGap(s,cost,reason,kind="spend"){
 const gap=Math.max(0,roundMoney(cost-s.account.cash));
 return [...(gap?[["borrow",gap,reason+"短借"]]:[]),[kind,cost,reason]];
}

