 if(s.turn===7)return seasonGame(s,"春季常规赛 · 正式首秀","debut","你满十八岁，联赛才发来选手证。上午还陪替补标过一遍观察点，现在你坐到了主队的椅子上，和"+teammate(s,s.team).name+"打揭幕场。",["首秀记下一场胜利。教练在首发名单上给你留了下一次训练时间。","首秀未能拿分。搭档保留了双方的视角，请你下周一起复盘。"],"early");
 if(s.turn===10)return seasonGame(s,"春季常规赛 · 客场","springAway",f.seat==="switched"?"转位后的客场首秀。教练把开场分工改成了你在试训时练的方案。":"离开主场的那一周，队里轮着带新人打客场。赛前搭档问你，开场光标要沿哪一条赛道递送。",["客场拿到一个胜场。","客场没拿到积分。队里约了返程后的一组对练。"]);
 if(s.turn===12)return seasonGame(s,"春季常规赛 · 收官","springClose","联赛只剩收官场。此前的逐场积分也算在内。你们要争的是春季淘汰赛席位，夏季的参赛资格要另打。",["你们赢下收官战，春季积分表封榜。","你们输掉收官战，春季积分表封榜。"]);
