function deltas(d){
 const tags=d.map((v,i)=>v===0?"":'<span class="'+(v<0?"down":"")+'">'+STATS[i]+' '+(v>0?"+":"−")+Math.abs(v)+'</span>').join("");
 return tags?'<div class="delta">'+tags+'</div>':"";
}
function factors(c){
 if(!c.weights)return "";
 const ordered=c.weights.map((v,i)=>[v,STATS[i]]).filter(([v])=>v).sort((a,b)=>b[0]-a[0]).map(([,n])=>n);
 return '<small class="chance-detail">判定依据 · '+ordered.join("、")+(c.bonus?' · '+c.reason+' +'+c.bonus+' 个百分点':'')+'</small>';
}
function statGrid(s){
 return '<div class="stats">'+s.stats.map((v,i)=>'<div class="stat" title="'+STAT_HELP[i]+'"><div class="stat-label"><span>'+STATS[i]+'</span><b>'+meter("s"+i,v)+'</b></div><div class="stat-line"><i style="width:'+v+'%"></i></div></div>').join("")+'</div>';
}
function profile(s){
 const portrait=s.team?"uniforms/"+s.sex+"_"+s.team:"stages/"+s.sex+"_rookie";
 return '<aside class="file-card"><div class="file-title"><h2>选手档案</h2><span>'+ageAt(s)+' 岁</span></div><div class="profile-art">'+img(portrait,s.team?teamName(s)+"队服选手形象":"青训选手形象")+'<span class="badge-team">'+(s.team?CLUBS[s.team].color+"队服":"青训候选")+'</span></div><div class="file-content"><p class="file-label">'+(s.role||"分路待定")+"　／　"+teamName(s)+'</p>'+statGrid(s)+finances(s)+honors(s)+'<p class="cashline">'+ticket(s)+(s.fit?' · 磨合 '+(s.fit>0?"+":"")+s.fit+' 点':'')+'</p><button class="file-link" data-act="journal">打开生涯手记 '+arrow+'</button><div class="pace-box"><button class="pace-link" data-act="pace">'+(quick?'节奏 · 即时':'节奏 · 实况')+'</button><button class="pace-link" data-act="profile">档案</button><button class="pace-link" data-act="album">相册</button></div></div></aside>';
}
function ended(){endingView();}
function dialog(title,body){$("#modalTitle").textContent=title;$("#modalBody").innerHTML=body;if(!mod.open)mod.showModal();mod.scrollTop=0;}
function menu(label,act,hint){return '<button data-act="'+act+'"><b>'+label+'</b><small>'+hint+'</small></button>';}
function help(){
 dialog("如何游玩",'<h3>十七岁进青训</h3><p>看录像、参加分组练习，然后选择角色和搭档。满十八岁后开始参加正式联赛，每段生涯的选择上限为三十轮。</p><h3>接力怎么计分</h3><p>队伍要把光标沿上、中、下三条赛道送过计分门。联络区可以换道，也可以会合。看清可见位置、队友距离和回位时间，再决定自己带标还是交给搭档；“HP”表示可用的竞技状态。</p><p>春季积累出场和配合经验，夏季争取赛区席位。进入世界赛后，要从分组阶段晋级八强、通过半决赛，才有机会争冠。单次接力的结果与整个八强系列赛分别判定。</p><h3>职业生涯</h3><p>天赋、性格、勤劳、健康和阵容磨合影响临场发挥。报价按万元计算，保底按期发放；现金、应收款、可退保证金和借款分开记。健康低于 28，或已有至少两次正式失利且性格低于 25，队伍会安排转岗。合同影响注册时仍可选择下一份工作。</p><h3>手记与存档</h3><p>查看训练室消息和手记，或去战术室单独练习。Demo 3.0 使用独立的生涯存档。存档留在这台设备的浏览器里，可导出后换设备继续。</p>');
}
function journal(){
 const s=career;if(!s)return;
 dialog("生涯手记",'<p class="intro">'+ORIGINS[s.origin].name+'　／　'+(s.role||"分路待定")+'　／　世界冠军 '+s.world+' · 赛区冠军 '+s.regional+'</p>'+finances(s)+
 (s.history.length?'<div class="logs">'+s.history.slice().reverse().map((e,i)=>'<details class="log" '+(i===0?"open":"")+'><summary><small>'+e.age+' 岁 · 第 '+e.turn+' 轮</small>'+esc(e.title)+'</summary><p><b>'+esc(e.choice)+'</b>　'+esc(e.text)+'</p>'+deltas(e.delta)+(e.entries?.length?'<p class="auto">'+esc(ledgerLines(e.entries))+'</p>':'')+(e.daily||[]).map(b=>'<p class="auto"><b>'+esc(b.who)+'</b>　'+esc(b.note)+'</p>'+deltas(b.delta)).join('')+(e.routine?'<p class="auto"><b>自动记事</b>　'+esc(e.routine.note)+'</p>'+deltas(e.routine.delta):"")+'</details>').join("")+'</div>':'<p class="empty">你的选手档案已经建立。做出开场选择，它就会被记在这里。</p>'));
}
function files(){dialog("生涯存档",'<p>这个浏览器保留一份当前生涯。导出文件后，可以在另一台设备读入。</p><div class="menu-list">'+(career?menu("导出当前生涯","export","保存一份可重新读入的存档文件。"):"")+menu("读入生涯存档","import","从文件恢复当时的事件和选择结果。")+(screen!=="home"?menu("返回封面","home","当前生涯仍可继续。"):"")+(career?menu("另开一份生涯","new","建立新档案时可以先导出当前生涯。"):"")+'</div>');}
function perform(act){
 if(act==="lab"){labMenu(labActive?labActive.role:career?.role||"上单");return;}if(act==="skip"){finishFlow();return;}if(act==="pace"){setPace();return;}if(act==="album"){showAlbum();return;}if(act==="profile"&&career){dialog("选手档案",profile(career)+(career.flags.hero?'<p class="small">近期合练角色　'+esc(career.flags.hero)+'</p>':"")+(career.team?rosterPanel(career):""));return;}if(act==="help"){help();return;}if(act==="journal"){journal();return;}if(act==="files"){files();return;}
 if(act==="export"&&career){
  const url=URL.createObjectURL(new Blob([JSON.stringify(pack(career))],{type:"application/json"}));
  const a=document.createElement("a");a.href=url;a.download="冠军之路-第"+career.turn+"轮-生涯存档.json";a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);return;
 }
 if(act==="import"){$("#loadFile").click();return;}
 if(act==="replaceImport"&&incoming){career=incoming;incoming=null;persist();screen="play";}
 else if(act==="new"){selection={sex:"m",origin:"shop"};screen="setup";}
 else if(act==="home"){screen="home";}
 else if(act==="continue"&&career){screen="play";}
 else if(act==="start"&&career){
   dialog("替换当前生涯？",'<p>确认建档会替换本机的当前生涯。需要保留旧路时，先导出一份存档。</p><div class="action-group">'+button("导出旧生涯","export","secondary")+button("确认建档","confirmStart")+'</div>');return;
 }
 else if(act==="start"||act==="confirmStart"){
   career=fresh(selection.sex,crypto.getRandomValues(new Uint32Array(1))[0],selection.origin);screen="play";persist();
 }else if(act==="next"&&career){if(!advance(career))return;persist();}
 else return;
 if(mod.open)mod.close();render();
}
document.addEventListener("click",e=>{
 const b=e.target.closest("button");if(!b)return;
 if(b.dataset.labrole){labMenu(b.dataset.labrole);return;}
 if(b.dataset.drill){showDrill(b.dataset.drill);return;}
 if(b.hasAttribute("data-labchoice")){markDrill(Number(b.dataset.labchoice));return;}
 if(b.dataset.frame&&MEMORY[b.dataset.frame]&&career){dialog(MEMORY[b.dataset.frame].title,photoFigure(career,b.dataset.frame,b.dataset.team||career.team));return;}
 if(b.hasAttribute("data-sex")||b.hasAttribute("data-origin")){
  if(b.dataset.sex)selection.sex=b.dataset.sex;else selection.origin=b.dataset.origin;
  const selector=b.dataset.sex?'[data-sex="'+b.dataset.sex+'"]':'[data-origin="'+b.dataset.origin+'"]';
  render(false);$(selector)?.focus({preventScroll:true});return;
 }
 if(b.hasAttribute("data-choice")&&screen==="play"&&career){takeChoice(Number(b.dataset.choice));return;}
 if(b.dataset.act)perform(b.dataset.act);
});
$("#labBtn").onclick=()=>labMenu(career?.role||"上单");$("#helpBtn").onclick=help;$("#journalBtn").onclick=journal;$("#fileBtn").onclick=files;$("#closeModal").onclick=()=>mod.close();
$("#loadFile").addEventListener("change",async e=>{
 const file=e.target.files[0];e.target.value="";if(!file)return;
 try{
  if(file.size>100000)throw Error("size");
  incoming=unpack(await file.text());
  dialog("读入这份生涯？",'<p>'+ageAt(incoming)+' 岁，第 '+incoming.turn+' 轮，'+(incoming.role||"分路待定")+'。确认读入会把它设为本机当前生涯。</p><div class="action-group">'+(career?button("先导出当前生涯","export","secondary"):"")+button("确认读入","replaceImport")+'</div>');
 }catch{incoming=null;dialog("无法读入",'<p>请选择 Demo 3.0 导出的生涯存档。当前进度仍然保留。</p>');}
});
try{const saved=localStorage.getItem(saveKey);if(saved)career=unpack(saved);}
catch{storageIssue="未能读取本机存档。你可以在“存档”中读入此前导出的备份，也可以开始新生涯。";}
render(false);
